SELECT c.concert_id, c.title, c.artist, c.venue, c.thumbnail, c.status , TO_CHAR(MIN(s.booking_open_at), 'YYYY-MM-DD HH24:MI') AS booking_start_at , TO_CHAR(MAX(s.booking_open_at), 'YYYY-MM-DD HH24:MI') AS booking_end_at , TO_CHAR(MIN(s.performance_date), 'YYYY-MM-DD HH24:MI') AS perform_start_at , TO_CHAR(MAX(s.performance_date), 'YYYY-MM-DD HH24:MI') AS perform_end_at , COUNT(s.schedule_id) AS schedule_count FROM concerts c LEFT JOIN concert_schedules s ON c.concert_id = s.concert_id
AND c.status = #{status}
GROUP BY c.concert_id, c.title, c.artist, c.venue, c.thumbnail, c.status ORDER BY CASE c.status WHEN 'ONGOING' THEN 1 WHEN 'UPCOMING' THEN 2 WHEN 'CLOSED' THEN 3 ELSE 9 END ASC, MIN(s.booking_open_at) ASC NULLS LAST, c.concert_id DESC

SELECT concert_id, title, artist, venue, description, thumbnail, status
FROM concerts
WHERE concert_id = #{concertId}
